// ============================================================================
// Tokenizer Implementations
// ============================================================================

trait BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Seq[Token] = {
    values.map(tokenize).toSeq
  }
}

class StringTokenizer(
  lowercase: Boolean = false,
  uppercase: Boolean = false,
  stripWhitespace: Boolean = true,
  maxLength: Option[Int] = None,
  prefix: String = "",
  suffix: String = ""
) extends BaseTokenizer[String] {

  def tokenize(value: String): Token = {
    var processed = value

    if (stripWhitespace) {
      processed = processed.trim
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (uppercase) {
      processed = processed.toUpperCase
    }

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    processed = prefix + processed + suffix

    val metadata = Map(
      "original_length" -> value.length,
      "processed_length" -> processed.length
    )

    Token(processed, TokenType.String, metadata)
  }
}

class NumericTokenizer(
  precision: Option[Int] = None,
  useScientific: Boolean = false,
  prefix: String = "",
  suffix: String = ""
) extends BaseTokenizer[Any] {

  def tokenize(value: Any): Token = {
    val numValue: BigDecimal = value match {
      case i: Int => BigDecimal(i)
      case l: Long => BigDecimal(l)
      case f: Float => BigDecimal(f.toDouble)
      case d: Double => BigDecimal(d)
      case bd: BigDecimal => bd
      case _ => throw new IllegalArgumentException(s"Unsupported numeric type: ${value.getClass}")
    }

    val formatted = precision match {
      case Some(p) => numValue.setScale(p, BigDecimal.RoundingMode.HALF_UP).toString
      case None => numValue.toString
    }

    val processed = prefix + formatted + suffix

    val metadata = Map(
      "original_value" -> value,
      "numeric_type" -> value.getClass.getSimpleName
    )

    Token(processed, TokenType.Numeric, metadata)
  }
}

class TemporalTokenizer(
  dateFormat: String = "yyyy-MM-dd",
  datetimeFormat: String = "yyyy-MM-dd'T'HH:mm:ss"
) extends BaseTokenizer[Any] {

  private val dateFormatter = DateTimeFormatter.ofPattern(dateFormat)
  private val datetimeFormatter = DateTimeFormatter.ofPattern(datetimeFormat)

  def tokenize(value: Any): Token = {
    val (formatted, temporalType) = value match {
      case d: LocalDate =>
        (d.format(dateFormatter), "date")
      case dt: LocalDateTime =>
        (dt.format(datetimeFormatter), "datetime")
      case _ =>
        throw new IllegalArgumentException(s"Unsupported temporal type: ${value.getClass}")
    }

    val metadata = Map(
      "temporal_type" -> temporalType,
      "format" -> (if (temporalType == "date") dateFormat else datetimeFormat)
    )

    Token(formatted, TokenType.Temporal, metadata)
  }
}
