  private val dateFormatter = DateTimeFormatter.ofPattern(dateFormat)
  private val datetimeFormatter = DateTimeFormatter.ofPattern(datetimeFormat)

  def tokenize(value: Any): Token = {
    val (formatted, temporalType) = value match {
      case d: LocalDate =>
        (d.format(dateFormatter), "date")
      case dt: LocalDateTime =>
        (dt.format(datetimeFormatter), "datetime")
      case _ =>
        throw new IllegalArgumentException(s"Unsupported temporal type: ${value.getClass}")
    }

    val metadata = Map(
      "temporal_type" -> temporalType,
      "format" -> (if (temporalType == "date") dateFormat else datetimeFormat)
    )

    Token(formatted, TokenType.Temporal, metadata)
  }
}
